package fetch

import (
	"net/http"
	"sync"
)

// Status codes returned in place of an HTTP status when a request fails.
const Failed = -1

// FetchAll downloads every URL concurrently and returns the status codes in input order.
func FetchAll(urls []string) []int {
	codes := make([]int, len(urls))
	var wg sync.WaitGroup
	for i, u := range urls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			resp, err := http.Get(u)
			if err != nil {
				codes[i] = Failed
				return
			}
			resp.Body.Close()
			codes[i] = resp.StatusCode
		}()
	}
	wg.Wait()
	return codes
}

// Healthy reports whether every status is a 2xx.
func Healthy(codes []int) bool {
	for _, c := range codes {
		if c < 200 || c > 299 {
			return false
		}
	}
	return true
}

