package pool

import "sync"

// Run calls fn on every job using at most workers goroutines and returns the first error.
func Run[T any](jobs []T, workers int, fn func(T) error) error {
	if workers < 1 {
		workers = 1
	}
	ch := make(chan T)
	var (
		wg	   sync.WaitGroup
		once	 sync.Once
		firstErr error
	)
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for job := range ch {
				if err := fn(job); err != nil {
					once.Do(func() { firstErr = err })
				}
			}
		}()
	}
	for _, job := range jobs {
		ch <- job
	}
	close(ch)
	wg.Wait()
	return firstErr
}

// Map applies fn to every item and returns the results in input order.
func Map[T, R any](items []T, workers int, fn func(T) (R, error)) ([]R, error) {
	out := make([]R, len(items))
	idx := make([]int, len(items))
	for i := range idx {
		idx[i] = i
	}
	err := Run(idx, workers, func(i int) error {
		r, err := fn(items[i])
		if err != nil {
			return err
		}
		out[i] = r
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

