package backup

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"os"
)

// Checksums returns the hex SHA-256 of each path.
func Checksums(paths []string) (map[string]string, error) {
	sums := make(map[string]string, len(paths))
	for _, p := range paths {
		f, err := os.Open(p)
		if err != nil {
			return nil, err
		}
		defer f.Close()
		h := sha256.New()
		if _, err := io.Copy(h, f); err != nil {
			return nil, err
		}
		sums[p] = hex.EncodeToString(h.Sum(nil))
	}
	return sums, nil
}

// Verify compares the files' checksums with the expected ones and returns the paths that differ.
func Verify(expected map[string]string) ([]string, error) {
	paths := make([]string, 0, len(expected))
	for p := range expected {
		paths = append(paths, p)
	}
	got, err := Checksums(paths)
	if err != nil {
		return nil, err
	}
	var bad []string
	for p, want := range expected {
		if got[p] != want {
			bad = append(bad, p)
		}
	}
	return bad, nil
}

