package chat

import "sync"

type Client struct {
	ID   string
	done chan struct{}
	out  chan string
}

func (c *Client) Send(msg string) {
	select {
	case c.out <- msg:
	default: // slow client: drop the message
	}
}

// Registry tracks connected clients.
type Registry struct {
	mu	  sync.RWMutex
	clients map[string]*Client
}

func NewRegistry() *Registry {
	return &Registry{clients: make(map[string]*Client)}
}

func (r *Registry) Add(c *Client) {
	r.mu.Lock()
	r.clients[c.ID] = c
	r.mu.Unlock()
}

func (r *Registry) Remove(id string) {
	r.mu.Lock()
	c := r.clients[id]
	delete(r.clients, id)
	r.mu.Unlock()
	close(c.done)
}

func (r *Registry) Broadcast(msg string) {
	for _, c := range r.clients {
		c.Send(msg)
	}
}

func (r *Registry) Count() int {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return len(r.clients)
}

