package partner

import (
	"encoding/json"
	"fmt"
	"net/http"
)

var client = &http.Client{}

// FetchJSON GETs url and decodes the JSON body into out.
func FetchJSON(url string, out any) error {
	resp, err := client.Get(url)
	if err != nil {
		return err
	}
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("fetch %s: status %d", url, resp.StatusCode)
	}
	defer resp.Body.Close()
	return json.NewDecoder(resp.Body).Decode(out)
}

// FetchAll fetches each url into a new value made by newValue.
func FetchAll[T any](urls []string) ([]T, error) {
	out := make([]T, 0, len(urls))
	for _, u := range urls {
		var v T
		if err := FetchJSON(u, &v); err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, nil
}

