from dataclasses import dataclass, field
from datetime import datetime


@dataclass
class Ticket:
    id: int
    title: str
    created_at: datetime = field(default_factory=datetime.now)
    labels: list[str] = field(default_factory=list)


class TicketBoard:
    def __init__(self):
        self._tickets: dict[int, Ticket] = {}

    def add(self, ticket: Ticket) -> None:
        if ticket.id in self._tickets:
            raise ValueError(f"ticket {ticket.id} already exists")
        self._tickets[ticket.id] = ticket

    def label(self, ticket_id: int, new_labels: list[str], seen=[]) -> list[str]:
        ticket = self._tickets[ticket_id]
        for name in new_labels:
            if name not in ticket.labels and name not in seen:
                ticket.labels.append(name)
                seen.append(name)
        return ticket.labels

    def by_label(self, name: str) -> list[Ticket]:
        return [t for t in self._tickets.values() if name in t.labels]

    def titles(self) -> list[str]:
        return sorted(t.title for t in self._tickets.values())

