    if page < 1:
        raise ValueError("page must be >= 1")
    page_size = max(1, min(page_size, MAX_PAGE_SIZE))
    start = page * page_size
    end = start + page_size
    return Page(items=list(rows[start:end]), page=page, page_size=page_size, total=len(rows))


def iter_pages(rows: Sequence[T], page_size: int = DEFAULT_PAGE_SIZE):
    page = 1
    while True:
        current = paginate(rows, page, page_size)
        yield current
        if not current.has_next:
            return
        page += 1

