import threading
import time
from typing import Callable


class TokenCache:
    """Caches API tokens per tenant and refreshes them shortly before they expire."""

    def __init__(self, fetch: Callable[[str], tuple[str, float]], skew: float = 30.0):
        self._fetch = fetch
        self._skew = skew
        self._tokens: dict[str, tuple[str, float]] = {}
        self._lock = threading.Lock()

    def _fresh(self, entry: tuple[str, float] | None) -> bool:
        return entry is not None and entry[1] - self._skew > time.time()

    def get(self, tenant: str) -> str:
        with self._lock:
            entry = self._tokens.get(tenant)
        if entry is not None and self._fresh(entry):
            return entry[0]
        token, expires_at = self._fetch(tenant)
        with self._lock:
            self._tokens[tenant] = (token, expires_at)
        return token

    def invalidate(self, tenant: str) -> None:
        with self._lock:
            self._tokens.pop(tenant, None)

    def size(self) -> int:
        with self._lock:
            return len(self._tokens)

