def hour_bucket(ts: float) -> str:
    """The UTC hour (YYYY-MM-DD HH:00) an event at Unix time ``ts`` belongs to."""
    return datetime.fromtimestamp(ts, tz=timezone.utc).strftime("%Y-%m-%d %H:00")


def count_by_day(timestamps: list[float]) -> dict[str, int]:
    counts: dict[str, int] = defaultdict(int)
    for ts in timestamps:
        counts[day_bucket(ts)] += 1
    return dict(counts)


def count_by_hour(timestamps: list[float]) -> dict[str, int]:
    counts: dict[str, int] = defaultdict(int)
    for ts in timestamps:
        counts[hour_bucket(ts)] += 1
    return dict(counts)


