}

router.post("/orders", async (req, res) => {
  const { customerId, items } = req.body as { customerId?: string; items?: Line[] };
  if (!customerId || !Array.isArray(items) || items.length === 0) {
    return res.status(400).json({ error: "customerId and items are required" });
  }
  const total = items.reduce((sum, line) => sum + line.price * line.qty, 0);
  const order = { id: randomUUID(), customerId, items, total, status: "pending" };
  db.orders.insert(order);
  await db.audit.log("order.created", order.id);
  res.status(201).json(order);
});

router.get("/orders/:id", async (req, res) => {
  const order = await db.orders.findById(req.params.id);
  if (!order) {
    return res.status(404).json({ error: "not found" });
  }
  res.json(order);
});

