import { useState } from "react";

export interface Comment {
  id: string;
  author: string;
  body: string;
  createdAt: string;
}

export function CommentList({ comments }: { comments: Comment[] }) {
  if (comments.length === 0) {
    return <p className="empty">No comments yet.</p>;
  }
  return (
    <ul className="comments">
      {comments.map((c) => (
        <li key={c.id}>
          <strong>{c.author}</strong>
          <div className="body" dangerouslySetInnerHTML={{ __html: c.body }} />
          <time dateTime={c.createdAt}>{new Date(c.createdAt).toLocaleString()}</time>
        </li>
      ))}
    </ul>
  );
}

export function CommentForm({ onSubmit }: { onSubmit: (body: string) => Promise<void> }) {
  const [body, setBody] = useState("");
  const [busy, setBusy] = useState(false);

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    const trimmed = body.trim();
    if (!trimmed || busy) return;
    setBusy(true);
    try {
      await onSubmit(trimmed);
      setBody("");
    } finally {
      setBusy(false);
    }
  }

  return (
    <form onSubmit={submit}>
      <textarea value={body} onChange={(e) => setBody(e.target.value)} />
      <button disabled={busy}>Post</button>
    </form>
  );
}

