import { useEffect, useState } from "react";

function pad(n: number): string {
  return n.toString().padStart(2, "0");
}

export function formatClock(totalSeconds: number): string {
  const clamped = Math.max(0, totalSeconds);
  return `${pad(Math.floor(clamped / 60))}:${pad(clamped % 60)}`;
}

export function Countdown({ seconds, onDone }: { seconds: number; onDone: () => void }) {
  const [left, setLeft] = useState(seconds);

  useEffect(() => {
    const id = setInterval(() => {
      setLeft(left - 1);
      if (left - 1 <= 0) {
        clearInterval(id);
        onDone();
      }
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <div role="timer" aria-live="off">
      Basket held for {formatClock(left)}
    </div>
  );
}

export function holdExpired(heldAt: number, now: number, holdSeconds: number): boolean {
  return now - heldAt >= holdSeconds * 1000;
}

