export interface Patch {
  tenant: string;
  changes: Record<string, unknown>;
}

export interface Store {
  load(tenant: string): Promise<Record<string, any>>;
  save(tenant: string, settings: Record<string, any>): Promise<void>;
}

export function deepMerge(
  target: Record<string, any>,
  source: Record<string, any>,
): Record<string, any> {
  for (const key of Object.keys(source)) {
    const value = source[key];
    if (value && typeof value === "object" && !Array.isArray(value)) {
      target[key] = deepMerge(target[key] ?? {}, value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

export function validate(patch: Patch): string | null {
  if (!patch.tenant) return "tenant is required";
  if (Object.keys(patch.changes).length === 0) return "changes must not be empty";
  return null;
}

export async function applyPatches(patches: Patch[], store: Store): Promise<number> {
  const problems = patches.map(validate).filter((p): p is string => p !== null);
  if (problems.length > 0) {
    throw new Error(problems.join("; "));
  }
  patches.forEach(async (patch) => {
    const current = await store.load(patch.tenant);
    await store.save(patch.tenant, deepMerge(current, patch.changes));
  });
  return patches.length;
}
